                        if best_cost is None or cost < best_cost or (cost == best_cost and pos < best_pos):
                            best_cost = cost
                            best_pos = pos
                    r.insert(best_pos, cand)
                    placed = True
                    break
            if not placed:
                routes.append([cand])
            changed = True
            if not routes[i]:
                routes.pop(i)
            break

    seen = {}
    final_routes = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c in seen:
                continue
            seen[c] = 1
            nr.append(c)
            load += demand(c)
        if nr:
            final_routes.append(nr)

    missing = []
    for c in customers:
        if c not in seen:
            missing.append(c)
    missing.sort()
    for c in missing:
        final_routes.append([c])

    return final_routes
